                    expectedSize, expectedSize, parent.getName(), size[0], size[1]);
            context.report(ISSUE, Location.create(file), message);
        }
    }

    private static Integer getExpectedSize(String folderName) {
        switch (folderName) {
            case "mipmap-mdpi":
