            case "mipmap-hdpi":
                return 72;
            case "mipmap-xhdpi":
                return 96;
            case "mipmap-xxhdpi":
                return 144;
            case "mipmap-xxxhdpi":
                return 192;
            default:
                return null;
        }
    }

    private static int[] readImageSize(File file) {
        try {
            BufferedImage image = ImageIO.read(file);
            if (image != null) {
                return new int[] { image.getWidth(), image.getHeight() };
            }
        } catch (IOException ignored) {
        }
        return null;
    }
}
